style.css:
@-moz-document domain("youtube.com") {
/* khóa thanh cuộn ngang do hiệu ứng ambient phóng to tràn khung */
    html,
    body,
    ytd-app,
    ytd-watch-flexy {
        overflow-x: hidden !important;
    }

    /* nền tím đậm trang xem video */
    ytd-watch-flexy {
        background: #100817 !important;
    }

    /* hiệu ứng Ambient Mode */
    ytd-watch-flexy #cinematics {
        transform: scale(1.35) !important;
        transform-origin: center center !important;
        filter:
            blur(32px)
            brightness(0.75)
            saturate(1.5) !important;
        opacity: 0.95 !important;
        pointer-events: none !important;
    }

    /* giữ video chính sắc nét */
    ytd-watch-flexy #movie_player {
        filter: none !important;
    }
}
